const root=getWorkspaceDir();mkdirSync(join(root,'.piclaw'),{recursive:true});mkdirSync(join(root,'.pi'),{recursive:true});writeFileSync(join(root,'.piclaw/config.json'),JSON.stringify({domains:{access:{mode:'single-user'}}}),{mode:0o600});writeFileSync(join(root,'.pi/mcp.json'),JSON.stringify({mcpServers:Object.fromEntries(Array.from({length:25},(_,n)=>[`server${n}`,{command:'never-run',args:['withheld-private-fixture'],requestTimeoutMs:5000}]))}),{mode:0o600});initDatabase();resetMcpStartupStateForTests();resetMcpCodemodeRuntimeForTests();await hydrateMcpKeychainCredentials(root,()=>{throw Error('No keychain allowed');});const controller=new McpCodemodeController({blockMcpAdmissions(){throw Error('No Apply');},async fenceMcpAndSnapshot(){throw Error('No Apply');},resumeMcpAdmissions(){throw Error('No Apply');},async quarantineMcpRuntime(){throw Error('No Apply');}});
const metrics:Record<string,{calls:number;ms:number}>={},restore:Array<()=>void>=[];const wrap=(object:any,key:string)=>{const original=object[key];object[key]=function(...args:any[]){const at=performance.now();try{return Reflect.apply(original,this,args);}finally{const row=metrics[key]??={calls:0,ms:0};row.calls++;row.ms+=performance.now()-at;}};restore.push(()=>{object[key]=original;});};wrap(JSON,'parse');wrap(JSON,'stringify');const db=getDb();wrap(db,'prepare');wrap(db,'query');
const channel={authGateway:{getPrincipal:()=>{db.query('SELECT 1').get();return{kind:'local',mode:'single-user',role:'admin',userId:'default',authentication:{method:'local',sessionId:null,expiresAt:null}};}},agentPool:{inspectMcpServers:(edit?:unknown)=>controller.inspectServers(edit)}} as any;
const loop=monitorEventLoopDelay({resolution:1});loop.enable();const cpu=process.cpuUsage(),start=performance.now();try{for(let n=0;n<100;n++){const edit=n%2===1;const req=new Request(`http://synthetic/agent/settings/mcp/servers${edit?'/preview':''}`,edit?{method:'POST',body:JSON.stringify({name:'server0',action:'update',patch:{requestTimeoutMs:6000+n}})}:{});const response=await handleMcpSettings(channel,req,new URL(req.url));assert.equal(response.status,200);const body=await response.text();assert(!body.includes('withheld-private-fixture'));if(n%10===0)await Bun.sleep(5);}await Bun.sleep(5);loop.disable();const usage=process.cpuUsage(cpu);console.log(JSON.stringify({kind:'mcp-server-settings-read-preview',requests:100,servers:25,diskDatabase:true,wallMs:performance.now()-start,cpuUs:usage,eventLoop:{maxMs:loop.max/1e6,p99Ms:loop.percentile(99)/1e6,samples:loop.count},methods:metrics,memory:process.memoryUsage(),scope:'isolated synthetic direct owner handler with disk SELECT1 authority probe; filesystem effective projection, no network/keychain/Apply/server/provider execution; not whole HTTP auth/CSRF or production benchmark'}));}
finally{loop.disable();for(const undo of restore.reverse())undo();closeDatabase();resetMcpStartupStateForTests();resetMcpCodemodeRuntimeForTests();}
